<?php
function sc_support_scope(){return in_array((int)userVariable('user_group'),[1,2],true)?'':' AND created_by='.(int)userVariable('id');}
function sc_support_ticket($id){if(!admin_can('support'))return null;return sc_query('SELECT * FROM support_tickets WHERE id=? AND COALESCE(reply_to_id,0)=0 AND is_deleted=0'.sc_support_scope(),'i',[(int)$id])->get_result()->fetch_assoc();}
function sc_support_submit($request){$action=$request['action']??'';$actor=sc_admin_guard('support',$action==='create'?'create':'update',$request);$id=(int)($request['ticket_id']??0);$title=trim($request['title']??'');$description=trim($request['description']??'');$type=trim($request['issue_type']??'Other');if(in_array($action,['create','reply'],true)&&(!$description||mb_strlen($description)>10000))throw new RuntimeException('Enter a description up to 10,000 characters.');if($action==='create'&&(!$title||mb_strlen($title)>50||mb_strlen($type)>50))throw new RuntimeException('Enter a title and issue type up to 50 characters.');if(!in_array($action,['create','reply','resolve','reopen'],true))throw new RuntimeException('Invalid ticket action.');if($action!=='create'&&!sc_support_ticket($id))throw new RuntimeException('Ticket not found or access denied.');
 $files=[];$dir=__DIR__.'/../system_generated/support/';if(!is_dir($dir))mkdir($dir,0775,true);$f=$_FILES['ticket_attachments']??null;
 try{if($f&&!empty(array_filter($f['name']))){if(count(array_filter($f['name']))>3)throw new RuntimeException('Attach up to three files.');foreach($f['name'] as $i=>$name){if($name==='')continue;if($f['error'][$i]!==UPLOAD_ERR_OK||$f['size'][$i]>1048576)throw new RuntimeException('Attachments must upload successfully and be at most 1 MB each.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name'][$i]);$ext=['application/pdf'=>'pdf','image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp','image/gif'=>'gif'][$mime]??null;if(!$ext)throw new RuntimeException('Only PDF, PNG, JPEG, WebP and GIF files are accepted.');$file=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'][$i],$dir.$file))throw new RuntimeException('Could not save attachment.');$files[]=$file;}}
 $db=sc_db();$db->begin_transaction();try{if($action==='create'||$action==='reply'){$ticketCode='SC-'.strtoupper(bin2hex(random_bytes(6)));sc_query("INSERT INTO support_tickets (ticketid,reply_to_id,site_name,site_url,title,issue_type,description,attachments,status,created_by,updated_by) VALUES (?,?,?,?,?,?,?,?,'Pending',?,?)",'sissssssii',[$ticketCode,$action==='reply'?$id:null,mb_substr(systemVariable('SITE_NAME'),0,50),mb_substr(sc_url(),0,100),$action==='reply'?'Reply':$title,$type,$description,json_encode($files),$actor['id'],$actor['id']]);$newId=$db->insert_id;if($action==='create')$id=$newId;else sc_query("UPDATE support_tickets SET status='Replied',updated_by=? WHERE id=?",'ii',[$actor['id'],$id]);}else{$status=$action==='resolve'?'Resolved':'Pending';sc_query('UPDATE support_tickets SET status=?,updated_by=? WHERE id=?','sii',[$status,$actor['id'],$id]);}sc_audit('support.'.$action,$id);$db->commit();return $id;}catch(Throwable $e){$db->rollback();throw $e;}
 }catch(Throwable $e){foreach($files as $file)if(is_file($dir.$file))unlink($dir.$file);throw $e;}
}
